mapping(string => mapping(uint256 => bool)) public destinationHandlers_whitelist; 

function addDestinationHandler(string memory chain, uint256 handler) public onlyOwner {
destinationHandlers_whitelist[chain][handler] = true; 
}

modifier IsValidDestinationHandler(string memory chain, uint2256 handler) {
require(destinationHandlers_whitelist[chain][handler] == true, "Not a valid handler"); 
_;
}
