        h = new Helper();
    }

    function test_readID() public {
        Message memory test_msg = Message(1, PayloadType.Raw, "0x1234");
        bytes memory encoded = MessageV1Codec.encode(test_msg);
        assertEq(h.readID(encoded), test_msg.id);
