# Vulnerability details

## Vulnerability details
After a cross-chain message has been sent using `cross_chain_erc20_settlement()` from a L1 (Etheruem) to any L2, the message will pass through the L1 sequencer. It is however not guaranteed that the message will processed by the sequencer, reasons for this could be a sudden surge in gas prices. Should an event like this occur the user/protocol has no way to cancel the ongoing message.

## Impact
The tokens locked into the `ChakraSettlementHandler` contract will be locked until the message goes through which could take an extremely long time.

## Proof of Concept
A cross-chain message is initiated using the `cross_chain_erc20_settlement()` function and tokens are transferred to the Ethereum contract address of the `ChakraSettlementHandler`. 

https://github.com/code-423n4/2024-08-chakra/blob/d0d45ae1d26ca1b87034e67180fac07ce9642fd9/solidity/handler/contracts/ChakraSettlementHandler.sol#L111-L223

```solidity
    function cross_chain_erc20_settlement(
        string memory to_chain,
        uint256 to_handler,
        uint256 to_token,
        uint256 to,
        uint256 amount
    ) external {
        require(amount > 0, "Amount must be greater than 0");
        require(to != 0, "Invalid to address");
        require(to_handler != 0, "Invalid to handler address");
        require(to_token != 0, "Invalid to token address");


        if (mode == SettlementMode.MintBurn) {
            _erc20_lock(msg.sender, address(this), amount);
        } else if (mode == SettlementMode.LockUnlock) {
            _erc20_lock(msg.sender, address(this), amount);
        } else if (mode == SettlementMode.LockMint) {
            _erc20_lock(msg.sender, address(this), amount);
        } else if (mode == SettlementMode.BurnUnlock) {
            _erc20_burn(msg.sender, amount);
        }


        {
            // Increment nonce for the sender
            nonce_manager[msg.sender] += 1;
        }


        // Create a new cross chain tx
        uint256 txid = uint256(
            keccak256(
                abi.encodePacked(
                    chain,
                    to_chain,
                    msg.sender, // from address for settlement to calculate txid
                    address(this), //  from handler for settlement to calculate txid
                    to_handler,
                    nonce_manager[msg.sender]
                )
            )
        );


        {
            // Save the cross chain tx
            create_cross_txs[txid] = CreatedCrossChainTx(
                txid,
                chain,
                to_chain,
                msg.sender,
                to,
                address(this),
                to_token,
                amount,
                CrossChainTxStatus.Pending
            );
        }


        {
            // Create a new cross chain msg id
            cross_chain_msg_id_counter += 1;
            uint256 cross_chain_msg_id = uint256(
                keccak256(
                    abi.encodePacked(
                        cross_chain_msg_id_counter,
                        address(this),
                        msg.sender,
                        nonce_manager[msg.sender]
                    )
                )
            );
            // Create a erc20 transfer payload
            ERC20TransferPayload memory payload = ERC20TransferPayload(
                ERC20Method.Transfer,
                AddressCast.to_uint256(msg.sender),
                to,
                AddressCast.to_uint256(token),
                to_token,
                amount
            );


            // Create a cross chain msg
            Message memory cross_chain_msg = Message(
                cross_chain_msg_id,
                PayloadType.ERC20,
                codec.encode_transfer(payload)
            );


            // Encode the cross chain msg
            bytes memory cross_chain_msg_bytes = MessageV1Codec.encode(
                cross_chain_msg
            );


            // Send the cross chain msg
            settlement.send_cross_chain_msg(
                to_chain,
                msg.sender,
                to_handler,
                PayloadType.ERC20,
                cross_chain_msg_bytes
            );
        }


        emit CrossChainLocked(
            txid,
            msg.sender,
            to,
            chain,
            to_chain,
            address(this),
            to_token,
            amount,
            mode
        );
    }
